-- EZBuild reference schema (SQL view of the Mongo 'products' collection)
CREATE TABLE products (
  sku VARCHAR(12) PRIMARY KEY,
  category VARCHAR(16) NOT NULL,
  brand VARCHAR(32) NOT NULL,
  name VARCHAR(120) NOT NULL,
  price_bdt INT NOT NULL,
  discount_percent TINYINT NOT NULL DEFAULT 0 CHECK (discount_percent BETWEEN 0 AND 90),
  stock INT NOT NULL DEFAULT 0,
  specs JSON,
  image VARCHAR(40),
  price_status VARCHAR(16) NOT NULL DEFAULT 'approx',
  active BOOLEAN NOT NULL DEFAULT TRUE
);
CREATE INDEX ix_cat_brand ON products(category, brand);
CREATE INDEX ix_price ON products(price_bdt);

